// Emits abis/index.ts from packages/contracts/out with `as const`, so Ponder and viem infer event and function
// types. packages/contracts/out is not committed, so the generated file is. Rerun after `forge build`.

import { readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const OUT = join(import.meta.dirname, "..", "..", "contracts", "out");
const TARGET = join(import.meta.dirname, "..", "abis", "index.ts");

const CONTRACTS = {
  mockUsdcAbi: "MockUSDC",
  zalFactoryAbi: "ZalFactory",
  canvasAccountAbi: "CanvasAccount",
  relationshipRegistryAbi: "RelationshipRegistry",
  zalInvoiceAbi: "ZalInvoice",
  zalFundingPoolAbi: "ZalFundingPool",
  zalVaultAbi: "ZalVault",
} as const;

const blocks = Object.entries(CONTRACTS).map(([name, artifact]) => {
  const path = join(OUT, `${artifact}.sol`, `${artifact}.json`);
  const abi: unknown = (JSON.parse(readFileSync(path, "utf8")) as { abi?: unknown }).abi;
  if (!Array.isArray(abi)) throw new Error(`${path}: abi is not an array`);
  return `export const ${name} = ${JSON.stringify(abi, null, 2)} as const;\n`;
});

writeFileSync(
  TARGET,
  `// Generated by scripts/gen-abis.ts from packages/contracts/out. Do not edit.\n\n${blocks.join("\n")}`,
);
console.log(`wrote ${TARGET}`);
